module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [9:0] accum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum <= 0;
        valid_out <= 0;
    end else begin
        if (valid_in) begin
            accum <= accum + {data_in, 2'b0};
            if (accum >= 10'd10000) begin
                data_out <= accum;
                valid_out <= 1;
                accum <= 0;
            end else begin
                valid_out <= 0;
            end
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule
